  correoDocente: 'kneira@utec.edu.pe',      // para pruebas puedes poner tu propio correo
  correoRemitente: 'aaron.vanoordt@utec.edu.pe',  // el mismo Gmail de la credencial SMTP
  githubOwner: 'aaronvanoordt-vanar',
  githubRepo: 'examen-final-zapatillas',
  githubRama: 'datos',
